from scale_generator import Scale


class ScaleTests(unittest.TestCase):
    def test_sharp_chromatic_tonics(self):
        pitches = ['A', 'A#', 'B', 'C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#']
        for tonic in ('C', 'a', 'G', 'D', 'A', 'E', 'B', 'F#',
                      'e', 'b', 'f#', 'c#', 'g#', 'd#'):
            with self.subTest(tonic=tonic):
                start = pitches.index(tonic.capitalize())
                self.assertEqual(Scale(tonic).chromatic(), pitches[start:] + pitches[:start])

    def test_flat_chromatic_tonics(self):
        pitches = ['A', 'Bb', 'B', 'C', 'Db', 'D', 'Eb', 'E', 'F', 'Gb', 'G', 'Ab']
        for tonic in ('F', 'Bb', 'Eb', 'Ab', 'Db', 'Gb',
                      'd', 'g', 'c', 'f', 'bb', 'eb'):
            with self.subTest(tonic=tonic):
                start = pitches.index(tonic.capitalize())
                self.assertEqual(Scale(tonic).chromatic(), pitches[start:] + pitches[:start])

    def test_g_major(self):
        self.assertEqual(Scale('G').interval('MMmMMMm'),
                         ['G', 'A', 'B', 'C', 'D', 'E', 'F#', 'G'])

    def test_flat_minor(self):
        self.assertEqual(Scale('d').interval('MmMMmMM'),
                         ['D', 'E', 'F', 'G', 'A', 'Bb', 'C', 'D'])

    def test_augmented_intervals(self):
        self.assertEqual(Scale('a').interval('MmMMmAm'),
                         ['A', 'B', 'C', 'D', 'E', 'F', 'G#', 'A'])

    def test_empty_and_partial_patterns(self):
        self.assertEqual(Scale('bb').interval(''), ['Bb'])
        self.assertEqual(Scale('B').interval('mM'), ['B', 'C', 'D'])

    def test_multiple_octaves(self):
        self.assertEqual(Scale('C').interval('A' * 8),
                         ['C', 'D#', 'F#', 'A', 'C', 'D#', 'F#', 'A', 'C'])

    def test_unicode_accidentals(self):
        self.assertEqual(Scale('F♯').chromatic(), Scale('F#').chromatic())
        self.assertEqual(Scale('e♭').chromatic(), Scale('eb').chromatic())

    def test_calls_do_not_change_the_scale(self):
        scale = Scale('F')
        expected = scale.chromatic()
        scale.interval('MMmMMMm')
        scale.chromatic().clear()
        self.assertEqual(scale.chromatic(), expected)
        self.assertEqual(scale.interval('M'), ['F', 'G'])


if __name__ == '__main__':
    unittest.main()
